mapper.select:
SELECT A.*, (SELECT COUNT(*) FROM meetup_applications WHERE meetup_id = a.meetup_id AND status = 'APPROVED' AND A.delete_yn = 'n') AS total_participants FROM meetups AS A WHERE A.delete_yn = 'N' AND A.status != 'DELETED'
AND A.status = #{status}
AND A.title LIKE CONCAT('%', #{searchText}, '%')
ORDER BY A.created_at DESC LIMIT #{start}, ${end}

